conv_transpose3d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <algorithm>
#define MAX_COUT 32
#define TILE_OH 4
#define TILE_OW 4
template<bool USE_SMEM, bool ONE_GROUP>
__global__ void conv_transpose3d_kernel_v2(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int D_in, int H_in, int W_in,
    int C_out, int D_out, int H_out, int W_out,
    int K,
    int stride, int padding, int output_padding, int dilation,
    int groups, int C_in_per_group, int C_out_per_group)
{
    extern __shared__ float smem[];
    int KKK = K * K * K;
    long weight_numel = (long)C_in * C_out_per_group * KKK;
    float* s_weight = nullptr;
    float* s_input_row;
    const float* w_ptr;
    if (USE_SMEM) {
        s_weight = smem;
        long w_vec4 = weight_numel / 4;
        const float4* w_src4 = reinterpret_cast<const float4*>(weight);
        float4* w_dst4 = reinterpret_cast<float4*>(s_weight);
        for (long i = threadIdx.x; i < w_vec4; i += blockDim.x) {
            w_dst4[i] = w_src4[i];
        }
        for (long i = w_vec4 * 4 + threadIdx.x; i < weight_numel; i += blockDim.x) {
            s_weight[i] = weight[i];
        }
        s_input_row = smem + weight_numel;
        w_ptr = s_weight;
    } else {
        s_input_row = smem;
        w_ptr = weight;
    }
    bool use_vec4_row = ((W_in & 3) == 0) && (((size_t)s_input_row) % 16 == 0);
    int n = blockIdx.x;
    int od = blockIdx.y;
    int oh_tile_start = blockIdx.z * TILE_OH;
    const float* input_base = input + (long)n * C_in * D_in * H_in * W_in;
    bool has_bias = (bias != nullptr);
    long input_row_elems = (long)C_in * W_in;
    int ow_stride = blockDim.x * TILE_OW;
    for (int oh_local = 0; oh_local < TILE_OH; oh_local++) {
        int oh = oh_tile_start + oh_local;
        if (oh >= H_out) break;
        for (int ow_base = 0; ow_base < W_out; ow_base += ow_stride) {
            int ow0 = ow_base + threadIdx.x * TILE_OW;
            int ow[TILE_OW];
            bool valid[TILE_OW];
            #pragma unroll
            for (int t = 0; t < TILE_OW; t++) {
                ow[t] = ow0 + t;
                valid[t] = (ow[t] < W_out);
            }
            float sum[TILE_OW][MAX_COUT];
            #pragma unroll
            for (int t = 0; t < TILE_OW; t++) {
                #pragma unroll
                for (int oc = 0; oc < C_out; oc++) sum[t][oc] = 0.0f;
            }
            for (int kd = 0; kd < K; kd++) {
                int id_nom = od + padding - kd * dilation;
                bool id_valid = (id_nom % stride == 0);
                int id = id_valid ? (id_nom / stride) : -1;
                if (id_valid && (id < 0 || id >= D_in)) id_valid = false;
                for (int kh = 0; kh < K; kh++) {
                    int ih_nom = oh + padding - kh * dilation;
                    bool ih_valid = (ih_nom % stride == 0);
                    int ih = ih_valid ? (ih_nom / stride) : -1;
                    if (ih_valid && (ih < 0 || ih >= H_in)) ih_valid = false;
                    __syncthreads();
                    if (id_valid && ih_valid) {
                        if (use_vec4_row) {
                            int w_vec = W_in >> 2;
                            long total_vec = (long)C_in * w_vec;
                            for (long i = threadIdx.x; i < total_vec; i += blockDim.x) {
                                int ic = (int)(i / w_vec);
                                int ivw = (int)(i % w_vec);
                                int iw_ = ivw << 2;
                                long idx = ((long)ic * D_in + id) * H_in * W_in + (long)ih * W_in + iw_;
                                float4 val = *reinterpret_cast<const float4*>(input_base + idx);
                                *reinterpret_cast<float4*>(&s_input_row[(long)ic * W_in + iw_]) = val;
                            }
                        } else {
                            for (long i = threadIdx.x; i < input_row_elems; i += blockDim.x) {
                                int ic = (int)(i / W_in);
                                int iw_ = (int)(i % W_in);
                                long idx = ((long)ic * D_in + id) * H_in * W_in + (long)ih * W_in + iw_;
                                s_input_row[i] = input_base[idx];
                            }
                        }
                    }
                    __syncthreads();
                    if (id_valid && ih_valid) {
                        for (int kw = 0; kw < K; kw++) {
                            int iw_nom[TILE_OW];
                            int iw[TILE_OW];
                            bool iw_valid[TILE_OW];
                            float in_val[TILE_OW];
                            #pragma unroll
                            for (int t = 0; t < TILE_OW; t++) {
                                iw_nom[t] = ow[t] + padding - kw * dilation;
                                iw_valid[t] = valid[t] && (iw_nom[t] % stride == 0);
                                iw[t] = iw_valid[t] ? (iw_nom[t] / stride) : -1;
                                if (iw_valid[t] && (iw[t] < 0 || iw[t] >= W_in)) iw_valid[t] = false;
                            }
                            int s_off = (kd * K + kh) * K + kw;
                            if (ONE_GROUP) {
                                for (int ic = 0; ic < C_in_per_group; ic++) {
                                    int ic_global = ic;
                                    #pragma unroll
                                    for (int t = 0; t < TILE_OW; t++) {
                                        in_val[t] = iw_valid[t] ? s_input_row[(long)ic_global * W_in + iw[t]] : 0.0f;
                                    }
                                    long weight_base_idx = (long)ic_global * C_out_per_group * KKK + s_off;
                                    #pragma unroll
                                    for (int oc_local = 0; oc_local < MAX_COUT; oc_local++) {
                                        if (oc_local >= C_out_per_group) break;
                                        float w = w_ptr[weight_base_idx + (long)oc_local * KKK];
                                        #pragma unroll
                                        for (int t = 0; t < TILE_OW; t++) {
                                            sum[t][oc_local] += in_val[t] * w;
                                        }
                                    }
                                }
                            } else {
                                for (int g = 0; g < groups; g++) {
                                    int ic_base = g * C_in_per_group;
                                    int oc_base = g * C_out_per_group;
                                    for (int ic = 0; ic < C_in_per_group; ic++) {
                                        int ic_global = ic_base + ic;
                                        #pragma unroll
                                        for (int t = 0; t < TILE_OW; t++) {
                                            in_val[t] = iw_valid[t] ? s_input_row[(long)ic_global * W_in + iw[t]] : 0.0f;
                                        }
                                        long weight_base_idx = (long)ic_global * C_out_per_group * KKK + s_off;
                                        #pragma unroll
                                        for (int oc_local = 0; oc_local < C_out_per_group; oc_local++) {
                                            float w = w_ptr[weight_base_idx + (long)oc_local * KKK];
                                            #pragma unroll
                                            for (int t = 0; t < TILE_OW; t++) {
                                                sum[t][oc_base + oc_local] += in_val[t] * w;
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            #pragma unroll
            for (int t = 0; t < TILE_OW; t++) {
                if (valid[t]) {
                    for (int oc = 0; oc < C_out; oc++) {
                        float val = sum[t][oc];
                        if (has_bias) val += bias[oc];
                        long out_idx = (((long)n * C_out + oc) * D_out + od) * H_out * W_out + (long)oh * W_out + ow[t];
                        output[out_idx] = val;
                    }
                }
            }
        }
    }
}
torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int output_padding,
    int dilation,
    int groups)
{
    input = input.contiguous();
    weight = weight.contiguous();
    int N = input.size(0);
    int C_in = input.size(1);
    int D_in = input.size(2);
    int H_in = input.size(3);
    int W_in = input.size(4);
    int K = weight.size(2);
    int C_out_per_group = weight.size(1);
    int C_out = C_out_per_group * groups;
    int C_in_per_group = C_in / groups;
    int D_out = (D_in - 1) * stride - 2 * padding + dilation * (K - 1) + output_padding + 1;
    int H_out = (H_in - 1) * stride - 2 * padding + dilation * (K - 1) + output_padding + 1;
    int W_out = (W_in - 1) * stride - 2 * padding + dilation * (K - 1) + output_padding + 1;
    auto output = torch::zeros({N, C_out, D_out, H_out, W_out}, input.options());
    const float* bias_ptr = nullptr;
    if (bias.defined() && bias.numel() > 0) {
        bias = bias.contiguous();
        bias_ptr = bias.data_ptr<float>();
    }
    TORCH_CHECK(C_out <= MAX_COUT, "C_out exceeds supported maximum for this kernel");
    int threads = 256;
    if (W_out < threads) threads = W_out;
    if (threads < 1) threads = 1;
    int oh_tiles = (H_out + TILE_OH - 1) / TILE_OH;
    dim3 grid((unsigned int)N, (unsigned int)D_out, (unsigned int)oh_tiles);
    long weight_numel = (long)C_in * C_out_per_group * K * K * K;
    long input_row_elems = (long)C_in * W_in;
    size_t weight_bytes = (size_t)weight_numel * sizeof(float);
    size_t input_row_bytes = (size_t)input_row_elems * sizeof(float);
    int device_id;
    cudaGetDevice(&device_id);
    int max_smem_optin = 0;
    cudaDeviceGetAttribute(&max_smem_optin, cudaDevAttrMaxSharedMemoryPerBlockOptin, device_id);
    size_t smem_with_weight = weight_bytes + input_row_bytes;
    bool use_smem = (weight_numel > 0 && smem_with_weight <= (size_t)max_smem_optin);
    bool one_group = (groups == 1);
    #define LAUNCH_KERNEL(SMEM_B, ONE_GROUP_B, SMEM_BYTES) \
        conv_transpose3d_kernel_v2<SMEM_B, ONE_GROUP_B><<<grid, threads, SMEM_BYTES>>>( \
            input.data_ptr<float>(), \
            weight.data_ptr<float>(), \
            bias_ptr, \
            output.data_ptr<float>(), \
            N, C_in, D_in, H_in, W_in, \
            C_out, D_out, H_out, W_out, \
            K, \
            stride, padding, output_padding, dilation, \
            groups, C_in_per_group, C_out_per_group)
    if (use_smem) {
        if (one_group) {
            cudaFuncSetAttribute(conv_transpose3d_kernel_v2<true, true>,
                                  cudaFuncAttributeMaxDynamicSharedMemorySize,
                                  (int)smem_with_weight);
            LAUNCH_KERNEL(true, true, smem_with_weight);
        } else {
            cudaFuncSetAttribute(conv_transpose3d_kernel_v2<true, false>,
                                  cudaFuncAttributeMaxDynamicSharedMemorySize,
                                  (int)smem_with_weight);
            LAUNCH_KERNEL(true, false, smem_with_weight);
        }
    } else {
        size_t smem_no_weight = input_row_bytes;
        int smem_attr = (smem_no_weight > (size_t)max_smem_optin) ? max_smem_optin : (int)smem_no_weight;
        if (one_group) {
            cudaFuncSetAttribute(conv_transpose3d_kernel_v2<false, true>,
                                  cudaFuncAttributeMaxDynamicSharedMemorySize,
                                  smem_attr);
            LAUNCH_KERNEL(false, true, smem_no_weight);
        } else {
            cudaFuncSetAttribute(conv_transpose3d_kernel_v2<false, false>,
                                  cudaFuncAttributeMaxDynamicSharedMemorySize,
                                  smem_attr);
            LAUNCH_KERNEL(false, false, smem_no_weight);
        }
    }
    #undef LAUNCH_KERNEL
    return output;
}
