class ModelNew(nn.Module):
    """
    Performs a transposed 3D convolution using a custom CUDA kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0,
                 output_padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()

        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.dilation = dilation
        self.groups = groups
        self.use_bias = bias

        # Weight layout matches nn.ConvTranspose3d: (in_channels, out_channels/groups, kD, kH, kW)
        self.weight = nn.Parameter(
            torch.empty(in_channels, out_channels // groups, kernel_size, kernel_size, kernel_size)
        )
        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)

        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
            fan_in = out_channels // groups
            bound = 1 / (fan_in ** 0.5) if fan_in > 0 else 0
            nn.init.uniform_(self.bias, -bound, bound)
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous().cuda()
        weight = self.weight.contiguous().cuda()
        if self.use_bias:
            bias = self.bias.contiguous().cuda()
        else:
            bias = torch.tensor([], device=x.device, dtype=x.dtype)

        return conv_transpose3d_module.conv_transpose3d_cuda(
            x, weight, bias,
            self.stride, self.padding, self.output_padding, self.dilation, self.groups
        )


